style.css:
@-moz-document domain("pinterest.com"), domain("www.pinterest.com") {
/* General background color */
  body {
      background-color: #1e1e1e !important; /* Dark grey background */
      color: #d3d3d3 !important; /* Light grey text */
  }

  /* Links */
  a, a:visited {
      color: #b0b0b0 !important; /* Light grey links */
  }

  a:hover {
      color: #ffffff !important; /* White on hover */
  }

  /* Entire Pinterest header (search bar, home, profile, etc.) */
  header, .globalNav, .NavBar, .SearchBox, .AppBase, .zI7.iyn.Hsu, .XiG.sLG.zI7.iyn {
      background-color: #2c2c2c !important; /* Dark grey for header */
      color: #d3d3d3 !important; /* Light grey text */
      border-bottom: 1px solid #444444 !important; /* Light grey border */
  }

  /* Header buttons (home, profile, notifications, etc.) */
  .globalNav .Icon {
      color: #d3d3d3 !important; /* Light grey icons */
  }

  .globalNav .Icon:hover {
      color: #ffffff !important; /* White on hover */
  }

  /* Pinterest header search bar */
  .SearchBox input, input[type="search"] {
      background-color: #3b3b3b !important; /* Dark grey background for search bar */
      color: #d3d3d3 !important; /* Light grey text in search */
      border: 1px solid #666666 !important; /* Lighter border for search input */
  }

  /* Search input hover and focus */
  .SearchBox input:hover, .SearchBox input:focus {
      background-color: #444444 !important; /* Slightly lighter on hover or focus */
      border: 1px solid #777777 !important; /* Lighter border on hover or focus */
  }

  /* Pin container and content */
  .pinterest-feed, .Pin, .Grid__Item, .Grid__Layout {
      background-color: #252525 !important; /* Darker grey for pin container */
      border: none !important; /* No border on pins */
      color: #d3d3d3 !important; /* Light grey text */
  }

  /* Pin image hover effect */
  .Pin:hover {
      opacity: 0.95 !important; /* Slightly reduce opacity on hover */
  }

  /* Sidebar */
  aside, .CategoryLinks {
      background-color: #2a2a2a !important; /* Darker grey sidebar */
      color: #d3d3d3 !important;
  }

  /* Buttons */
  button, .Button {
      background-color: #333333 !important; /* Dark button background */
      color: #d3d3d3 !important; /* Light grey text on buttons */
      border: 1px solid #444444 !important; /* Light grey border */
  }

  button:hover, .Button:hover {
      background-color: #444444 !important; /* Slightly lighter on hover */
      border: 1px solid #555555 !important; /* Lighter border on hover */
  }

  /* Footer */
  footer {
      background-color: #2a2a2a !important; /* Dark footer */
      color: #d3d3d3 !important;
  }

  /* Remove the image filter to fix distorted images */
  img {
      filter: none !important;
  }
}
